using DriveOS.Modules.CurriculumPedagogy.Application.RemediationPlans;using DriveOS.SharedKernel.Identifiers;using Microsoft.EntityFrameworkCore;
namespace DriveOS.Modules.CurriculumPedagogy.Infrastructure.Read;
internal sealed class RemediationPlanReadService(Persistence.CurriculumPedagogyDbContext db):IRemediationPlanReadService{public async Task<IReadOnlyCollection<RemediationPlanResponse>>ListAsync(OrganizationId org,TrainingPathId path,CancellationToken ct=default){var xs=await db.RemediationPlans.AsNoTracking().Where(x=>x.OrganizationId==org&&x.TrainingPathId==path).Include(x=>x.Targets).OrderByDescending(x=>x.PlanCreatedAtUtc).ToListAsync(ct);return xs.Select(Map).ToArray();}public async Task<RemediationPlanResponse?>GetAsync(OrganizationId org,RemediationPlanId id,CancellationToken ct=default){var x=await db.RemediationPlans.AsNoTracking().Include(x=>x.Targets).SingleOrDefaultAsync(x=>x.OrganizationId==org&&x.Id==id,ct);return x is null?null:Map(x);}private static RemediationPlanResponse Map(Domain.RemediationPlans.RemediationPlan x)=>new(x.Id.Value,x.StudentId.Value,x.TrainingPathId.Value,x.ResponsibleUserId.Value,x.SourcePedagogicalReviewId?.Value,x.Recommendation,x.RecommendedPracticalHours,x.RecommendedSessions,x.ReviewDate,x.Status.ToString(),x.PlanCreatedAtUtc,x.ActivatedAtUtc,x.CompletedAtUtc,x.CancelledAtUtc,x.CancellationReason,x.Targets.Select(t=>new RemediationTargetResponse(t.Id.Value,t.CompetencyId.Value,t.Objective)).ToArray());}
